// 有限公务页只显示本人亲见的签受，真正交接只给受命本人读军事原记录。
#include "political_military_appointments_profile.hpp"
#include "political_military_appointments_detail.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using A=V::Array;
bool knows(const std::vector<StableId>& witnesses,const StableId& actor){return std::find(witnesses.begin(),witnesses.end(),actor)!=witnesses.end();}
}
BoundaryValue encode_political_military_appointment_quote(const PoliticalMilitaryAppointmentQuote& q){StableId world;const char* hex="0123456789abcdef";for(auto b:q.identity.world_id){world.push_back(hex[b>>4]);world.push_back(hex[b&15]);}return boundary::obj({{"identity",boundary::obj({{"world_id",V{world}},{"execution_epoch",V{q.identity.execution_epoch}},{"revision",V{q.identity.revision}},{"tick",V{q.identity.tick}}})},{"actor_id",V{q.actor_id}},{"duration",V{Integer{0}}},{"command_kind",V{q.kind}},{"command",encode_political_military_appointment_command(q.command)}});}
Outcome<BoundaryValue> merge_political_military_appointment_page(const PoliticalMilitaryAppointmentContext& c,const StableId& actor,const StableId& site,BoundaryValue page){
    if(!c.catalog.enabled)return {true,std::move(page),{}};if(actor!=c.common.state().metadata.player_actor_id)return {false,{},common_failure("PoliticalMilitaryObserverDenied").error};auto at=c.common.resolved_location(actor);const auto* here=at.ok?std::get_if<SettlementLocation>(&at.value):nullptr;if(!here||here->place_id!=site)return {false,{},common_failure("PlaceNotObservable",site).error};auto* container=page.find("rows");auto* rows=container?container->as<A>():nullptr;if(!rows)return {false,{},common_failure("PoliticalMilitaryPageRequired").error};
    auto history=political_military_detail::audit(c);if(!history.ok)return {false,{},history.error};CommonPresentation presentation(c.common.state(),c.common_catalog);std::size_t shown=0,inspected=0;bool truncated=false;
    auto action=[&](const StableId& text,const PoliticalMilitaryAppointmentCommand& command){auto q=preview_political_military_appointment(c,actor,command);return boundary::obj({{"text",V{text}},{"command",V{political_military_appointment_command_kind(command)}},{"params",encode_political_military_appointment_command(command)},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}}});};
    for(auto it=c.state.authorizations.rows().rbegin();it!=c.state.authorizations.rows().rend();++it){if(++inspected>128||shown>=16){truncated=true;break;}const auto& issued=it->second;if(actor!=issued.authority.actor_id&&actor!=issued.target.next_actor_id)continue;const auto* policy=c.catalog.policies.find(issued.policy_id);A actions;StableId text="已当面送达调任命令，尚未亲见后续答复。",source=issued.id;Integer observed=issued.tick,deadline=issued.answer_before_tick;const auto answer=history.value.answers.find(issued.id);const auto withdrawal=history.value.withdrawals.find(issued.id);bool final=false;
        if(answer!=history.value.answers.end()&&knows(answer->second->witness_actor_ids,actor)){const auto& v=*answer->second;source=v.id;observed=v.tick;deadline=v.accepted?v.apply_before_tick:issued.answer_before_tick;final=!v.accepted;text=v.accepted?"本人已受命；须到原营地办理交接，实际指挥归属以军旅记录为准。":"本人已婉拒，原指挥与部队资产保持。";}
        if(withdrawal!=history.value.withdrawals.end()&&knows(withdrawal->second->witness_actor_ids,actor)){source=withdrawal->second->id;observed=withdrawal->second->tick;final=true;text="原签发人已撤回此调任。";}
        if(actor==issued.target.next_actor_id&&answer!=history.value.answers.end()&&answer->second->accepted&&c.units.application){auto applied=c.units.application(issued.id);if(!applied.ok)return {false,{},applied.error};if(applied.value){const auto& v=*applied.value;const auto* head=c.common.state().facts.find(v.id);if(!head||head->kind!="military_officer_assignment"||head->domain!="military"||v.authorization_fact_id!=issued.id||v.acceptance_fact_id!=answer->second->id||v.actor_id!=actor||v.tick<answer->second->tick||v.tick>c.common.tick())return {false,{},common_failure("PoliticalMilitaryApplicationNoticeMismatch").error};source=v.id;observed=v.tick;final=true;text="本人已在营完成真实交接；军旅页保留原部队与历次指挥记录。";}}
        if(!final&&c.common.tick()>=deadline){final=true;text+="这份已知公文的期限已过，未亲见的后续结果仍待获知。";}
        if(!final&&actor==issued.target.next_actor_id){if(answer==history.value.answers.end()){actions.push_back(action("接受调任",PoliticalMilitaryAnswerCommand{issued.id,true}));actions.push_back(action("婉拒调任",PoliticalMilitaryAnswerCommand{issued.id,false}));}else if(answer->second->accepted){auto allowed=c.units.application_preview?c.units.application_preview(actor,issued.id,answer->second->id):common_failure("MilitaryOfficerAppointmentReadRequired");actions.push_back(boundary::obj({{"text",V{"在营地办理部队交接"}},{"command",V{"military_officer_assign"}},{"params",boundary::obj({{"request_key",V{"appointment:"+issued.id}},{"authorization_fact_id",V{issued.id}},{"acceptance_fact_id",V{answer->second->id}}})},{"available",V{allowed.ok}},{"code",V{allowed.ok?StableId{}:allowed.error.original.code}}}));}}
        if(!final&&actor==issued.authority.actor_id){const auto* office=c.organizations.offices.find(issued.authority.office_id);if(office&&office->holder_actor_id==std::optional<StableId>{actor})actions.push_back(action("撤回调任",PoliticalMilitaryWithdrawCommand{{office->organization_id,office->id,office->epoch,actor},issued.id}));}
        auto name=presentation.display_name(issued.target.next_actor_id);if(!name.ok)return {false,{},name.error};auto unit_name=c.units.unit_name?c.units.unit_name(issued.target.unit_id):Outcome<StableId>{false,{},common_failure("PoliticalMilitaryUnitNameRequired").error};if(!unit_name.ok)return {false,{},unit_name.error};rows->push_back(boundary::obj({{"kind",V{"military_appointment"}},{"id",V{issued.id}},{"display_name",V{unit_name.value+" · "+name.value}},{"text",V{text}},{"source_fact_id",V{source}},{"observed_tick",V{observed}},{"expires_tick",V{deadline}},{"terms_text",V{"只针对具名部队的原指挥来源；接受不改变军资、兵员、公职或私产。到场后仍须核双方空闲、离战和营地权源。"}},{"seat_place_id",V{policy->site_id}},{"actions",V{std::move(actions)}}}));++shown;
    }
    // 签发按钮只在该营地出现，且每一个候选仍走完整同一预览，不按可见人物自动下令。
    if(c.units.at_garrison)for(const auto& row:c.catalog.policies.rows()){if(shown>=16){truncated=true;break;}const auto& policy=row.second;if(policy.site_id!=site)continue;for(const auto& held:c.organizations.offices.rows()){if(++inspected>256){truncated=true;break;}const auto& office=held.second;if(office.holder_actor_id!=std::optional<StableId>{actor})continue;ActingAuthority authority{office.organization_id,office.id,office.epoch,actor};auto granted=political_military_detail::current_authority(c,authority,policy);if(!granted.ok)continue;auto units=c.units.at_garrison(policy.garrison_id);if(!units.ok)return {false,{},units.error};A actions;
        for(const auto& unit:units.value){if(++inspected>256||actions.size()>=16){truncated=true;break;}if(!political_military_detail::same_identity(unit.source_identity,c.common.state().identity)||unit.garrison_id!=policy.garrison_id)return {false,{},common_failure("PoliticalMilitarySourceMismatch").error};for(const auto& person:c.common.actor_order()){if(++inspected>256||actions.size()>=16){truncated=true;break;}PoliticalMilitaryIssueCommand command{authority,policy.id,{unit.organization_id,unit.garrison_id,unit.unit_id,unit.commander_actor_id,person,unit.command_source}};auto valid=preview_political_military_appointment(c,actor,command);if(!valid.ok)continue;auto name=presentation.display_name(person);if(!name.ok)return {false,{},name.error};auto unit_name=c.units.unit_name?c.units.unit_name(unit.unit_id):Outcome<StableId>{false,{},common_failure("PoliticalMilitaryUnitNameRequired").error};if(!unit_name.ok)return {false,{},unit_name.error};actions.push_back(action("向"+name.value+"提出接掌"+unit_name.value,command));}}
        if(!actions.empty()){rows->push_back(boundary::obj({{"kind",V{"military_appointment_policy"}},{"id",V{policy.id}},{"display_name",V{"营内军官调任"}},{"text",V{"当面交付具名部队命令，由受任本人另行答复与办理。"}},{"terms_text",V{"此授权不允许野外军团、舟队或交战部队换帅；军资、兵员和原债务均保留。"}},{"actions",V{std::move(actions)}}}));++shown;}
    }}
    if(truncated){auto* v=page.find("truncated");if(v)*v=V{true};else page.as<V::Dict>()->push_back({"truncated",V{true}});}return {true,std::move(page),{}};
}
}
